//! 工作区方案与技能回执的事务规则；复用行仓储，但通过execution命名空间隔离其他学习数据。
use rusqlite::{Connection,params};
use crate::learning_store;
fn put(db:&Connection,scope:&str,kind:&str,uid:&str,value:&str)->rusqlite::Result<()>{db.execute("INSERT INTO learning_records(scope,kind,uid,value) VALUES(?1,?2,?3,?4) ON CONFLICT(scope,kind,uid) DO UPDATE SET value=excluded.value",params![scope,kind,uid,value])?;Ok(())}
/// revision与方案身份共同判断替换；执行中的未知结果不能被新方案或普通丢弃覆盖。
pub fn save_plan(db:&mut Connection,scope:&str,uid:&str,expected:u64,value:Option<&str>,expected_uid:Option<&str>)->rusqlite::Result<bool>{
 let tx=db.transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)?;let prior=learning_store::read(&tx,scope,"plans",uid)?;
 let prior=prior.as_ref().map(|raw|serde_json::from_str::<serde_json::Value>(raw)).transpose().map_err(|_|rusqlite::Error::InvalidQuery)?;
 let before=prior.as_ref().and_then(|v|v.get("plan"));let revision=before.and_then(|v|v.get("revision")).and_then(|v|v.as_u64()).unwrap_or(0);
 if revision!=expected||before.and_then(|p|p["uid"].as_str())!=expected_uid{return Ok(false)}
 if let Some(value)=value{let next:serde_json::Value=serde_json::from_str(value).map_err(|_|rusqlite::Error::InvalidQuery)?;let p=&next["plan"];
  if p["revision"].as_u64()!=expected.checked_add(1){return Ok(false)}
  if let Some(before)=before{let replaceable=before["status"]=="completed"||(before["status"]=="draft"&&before["actions"].as_array().is_some_and(|a|a.is_empty()));if !replaceable&&(before["uid"]!=p["uid"]||before["scope"]!=p["scope"]){return Ok(false)}}
  put(&tx,scope,"plans",uid,value)?;
 }else{if before.is_some_and(|p|p["uid"].as_str()!=expected_uid){return Ok(false)}if before.is_some_and(|p|p["status"]=="applying"||p["status"]=="partial"){return Ok(false)}tx.execute("DELETE FROM learning_records WHERE scope=?1 AND kind='plans' AND uid=?2",params![scope,uid])?;}
 tx.commit()?;Ok(true)
}
/// 回执是首次完成的本机事实；重复完成保持原摘要/时点，不覆盖成另一次执行。
pub fn insert_once(db:&mut Connection,scope:&str,kind:&str,uid:&str,value:&str)->rusqlite::Result<()>{let tx=db.transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)?;tx.execute("INSERT OR IGNORE INTO learning_records(scope,kind,uid,value) VALUES(?1,?2,?3,?4)",params![scope,kind,uid,value])?;tx.commit()}
/// 明确清理当前未执行方案；发现任何未完成执行则整体拒绝，不部分删除恢复证据。
pub fn clear_plans(db:&mut Connection,scope:&str)->rusqlite::Result<bool>{let tx=db.transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)?;let blocked:i64=tx.query_row("SELECT count(*) FROM learning_records WHERE scope=?1 AND kind='plans' AND json_extract(value,'$.plan.status') IN ('applying','partial')",[scope],|r|r.get(0))?;if blocked>0{return Ok(false)}tx.execute("DELETE FROM learning_records WHERE scope=?1 AND kind='plans'",[scope])?;tx.commit()?;Ok(true)}
#[cfg(test)]mod tests{
 use super::*;
 fn plan(uid:&str,revision:u64,status:&str)->String{serde_json::json!({"key":"key","plan":{"uid":uid,"revision":revision,"status":status,"scope":{"areaUid":""},"actions":[{"key":"stable"}]}}).to_string()}
 #[test]fn revision_identity_and_partial_discard_are_transactional(){let mut db=Connection::open_in_memory().unwrap();learning_store::initialize(&db).unwrap();assert!(save_plan(&mut db,"execution:a","session",0,Some(&plan("one",1,"draft")),None).unwrap());assert!(!save_plan(&mut db,"execution:a","session",0,Some(&plan("two",1,"draft")),None).unwrap());assert!(save_plan(&mut db,"execution:a","session",1,Some(&plan("one",2,"partial")),Some("one")).unwrap());assert!(!save_plan(&mut db,"execution:a","session",2,None,Some("one")).unwrap());assert!(!save_plan(&mut db,"execution:a","session",2,Some(&plan("two",3,"partial")),Some("one")).unwrap());assert!(save_plan(&mut db,"execution:a","session",2,Some(&plan("one",3,"completed")),Some("one")).unwrap());assert!(save_plan(&mut db,"execution:a","session",3,None,Some("one")).unwrap());assert!(save_plan(&mut db,"execution:a","session",0,Some(&plan("two",1,"draft")),None).unwrap());assert!(!save_plan(&mut db,"execution:a","session",1,Some(&plan("one",2,"draft")),Some("one")).unwrap());assert!(!save_plan(&mut db,"execution:a","session",1,None,Some("one")).unwrap());assert!(learning_store::read(&db,"execution:b","plans","session").unwrap().is_none());}
 #[test]fn first_receipt_survives_reopen_and_failed_insert(){let dir=tempfile::tempdir().unwrap();let path=dir.path().join("profile.db");{let mut db=Connection::open(&path).unwrap();learning_store::initialize(&db).unwrap();insert_once(&mut db,"execution:a","receipts","call","first").unwrap();}let mut db=Connection::open(&path).unwrap();insert_once(&mut db,"execution:a","receipts","call","second").unwrap();assert_eq!(learning_store::read(&db,"execution:a","receipts","call").unwrap().as_deref(),Some("first"));db.execute_batch("CREATE TRIGGER reject_receipt BEFORE INSERT ON learning_records WHEN NEW.uid='fail' BEGIN SELECT RAISE(ABORT,'synthetic full'); END").unwrap();assert!(insert_once(&mut db,"execution:a","receipts","fail","unknown").is_err());assert!(learning_store::read(&db,"execution:a","receipts","fail").unwrap().is_none());}
 #[test]fn bulk_clear_preserves_unknown_progress_and_other_scopes(){let mut db=Connection::open_in_memory().unwrap();learning_store::initialize(&db).unwrap();save_plan(&mut db,"execution:a","one",0,Some(&plan("one",1,"draft")),None).unwrap();save_plan(&mut db,"execution:a","two",0,Some(&plan("two",1,"partial")),None).unwrap();assert!(!clear_plans(&mut db,"execution:a").unwrap());assert!(learning_store::read(&db,"execution:a","plans","one").unwrap().is_some());save_plan(&mut db,"execution:b","one",0,Some(&plan("other",1,"draft")),None).unwrap();assert!(clear_plans(&mut db,"execution:b").unwrap());assert!(learning_store::read(&db,"execution:a","plans","two").unwrap().is_some());}
}
